{var path=UnityEditor.AssetDatabase.GUIDToAssetPath(guid);var mesh=UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Mesh>(path);var name=System.IO.Path.GetFileNameWithoutExtension(path);if(mesh.name!=name){mesh.name=name;UnityEditor.EditorUtility.SetDirty(mesh);}}
